import * as dbModule from '$lib/server/db/drizzle';
const db = dbModule.default as any;
import type { RequestHandler } from './$types.js';

export const POST: RequestHandler = async ({ request }) => {
  try {
    const { caseId, canvasState } = await request.json();

    if (!caseId || !canvasState) {
      return json({ error: 'Case ID and canvas state are required' }, { status: 400 });
    }

    // Check if canvas state already exists for this case
    const existing = await db.select().from(canvasStates).where(eq(canvasStates.caseId, caseId)).limit(1);

    let result: typeof canvasStates.$inferSelect ;
    if (existing.length > 0) {
      // Update existing canvas state
      [result] = await db
        .update(canvasStates)
        .set({
          canvasData: canvasState,
          updatedAt: new Date(),
          version: (existing[0].version || 1) + 1
        })
        .where(eq(canvasStates.caseId, caseId))
        .returning();
    } else {
      // Create new canvas state
      [result] = await db
        .insert(canvasStates)
        .values({
          id: randomUUID(),
          caseId,
          name: `Canvas State ${new Date().toISOString()}`,
          canvasData: canvasState,
          version: 1,
          createdBy: null, // Set to actual user ID when available
        })
        .returning();
    }

    return json({ success: true, canvasState: result, message: 'Canvas state saved successfully' });
  } catch (error: Error | unknown) {
    console.error('Canvas save error:', error);
    return json(
      {
        error: 'Failed to save canvas state',
        details: error instanceof Error ? error.message : 'Unknown error'
      },
      { status: 500 }
    );
  }
};

