				severity: statute.severity,
				victimClass: statute.victimClass,
				bundled: statute.bundledCharges.map((c) => c.citation)
			});
		}

		return json(statute);
	} catch (error) {
		console.error('Statute fetch error:', error);
		return json({ error: 'Failed to fetch statute' }, { status: 500 });
