import type { RequestHandler } from '@sveltejs/kit';
import type { PhoenixWrightSearchResult } from '$lib/types/scoring';
import puppeteer from 'puppeteer';

export const POST: RequestHandler = async ({ request }) => {
  try {
    const { caseId, result, format }: {
      caseId: string;
      result: PhoenixWrightSearchResult;
      format: 'pdf' | 'json';
    } = await request.json();

    if (format === 'json') {
      return new Response(
        JSON.stringify(result, null, 2),
        {
          status: 200,
          headers: {
            'Content-Type': 'application/json',
            'Content-Disposition': `attachment; filename="phoenix-wright-search-${caseId}.json"`
          }
        }
      );
    }

    if (format === 'pdf') {
      // Generate HTML for PDF
      const html = generateSearchReportHTML(caseId, result);

      // Launch Puppeteer and generate PDF
      const browser = await puppeteer.launch({
        headless: true,
        args: ['--no-sandbox', '--disable-setuid-sandbox']
      });

      const page = await browser.newPage();
      await page.setContent(html, { waitUntil: 'networkidle0' });

      const pdfBuffer = await page.pdf({
        format: 'A4',
        printBackground: true,
        margin: {
          top: '1in',
          right: '1in',
          bottom: '1in',
          left: '1in'
        }
      });

      await browser.close();

      return new Response(Buffer.from(pdfBuffer), {
        status: 200,
        headers: {
          'Content-Type': 'application/pdf',
          'Content-Disposition': `attachment; filename="phoenix-wright-search-${caseId}.pdf"`
        }
      });
    }

    return new Response(
      JSON.stringify({ error: 'Unsupported format' }),
      { status: 400 }
    );

  } catch (error) {
    console.error('Phoenix Wright export error:', error);

    return new Response(
      JSON.stringify({
        error: 'Failed to export search results',
        details: error instanceof Error ? error.message : 'Unknown error'
      }),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' }
      }
    );
  }
};

