import { json, type RequestHandler } from '@sveltejs/kit';
import { db } from '$lib/server/db/client';
import { routeHealth } from '$lib/server/db/schema';
// @ts-ignore
import routeGraph from '$lib/phase72/route-ast-graph.json';

export const GET: RequestHandler = async () => {
    try {
        // Fetch all health records
        const healthRecords = await db.select().from(routeHealth);
        const healthMap = new Map(healthRecords.map(h => [h.routePath, h]));

        // Parse AST nodes
        const nodes = routeGraph.nodes || [];

        // Merge info
        const routes = nodes.map((node: any) => {
            const health = healthMap.get(node.id) || healthMap.get(node.path);
            return {
                ...node,
                status: health?.state || 'healthy', // Default to healthy if no record
                recentErrors: health?.recentErrorCount || 0,
                lastErrorAt: health?.lastErrorAt,
                clusterId: health?.lastErrorClusterId
            };
        });

        // If AST is empty (Phase 72 not run), return DB records as fallback routes
        if (routes.length === 0 && healthRecords.length > 0) {
            return json({
                routes: healthRecords.map(h => ({
                    id: h.routePath,
                    path: h.routePath,
                    file: h.file || 'unknown',
                    kind: 'unknown',
                    status: h.state,
                    recentErrors: h.recentErrorCount,
                    lastErrorAt: h.lastErrorAt
                }))
            });
        }

        return json({ routes });

    } catch (err) {
        console.error('[Phase78] Failed to list routes:', err);
        return json({ error: 'Failed to list routes' }, { status: 500 });
    }
};

